import * as U from '../ui.js';
import {timetableLayout,rowCells,clockLabel} from '../schedule-layout.js';
const {db,mount,heading,button,section,tag,esc,icon,edit}=U;
let offset=0,view=innerWidth<=640?'list':'week',courseFilter='';
const start=()=>{let d=new Date(U.TODAY+'T12:00Z');d.setUTCDate(d.getUTCDate()-((d.getUTCDay()+1)%7)+offset*7);return d};
const kind=s=>db.schedules.find(x=>x.id===s.schedule_id)?.title||'Class';
const shortTime=v=>U.time(v);
function weekBoard(days,sessions){const layout=timetableLayout(sessions,U.day,U.time),headers=[];for(let from=layout.start;from<layout.end;from+=120){const until=Math.min(from+120,layout.end);headers.push(`<th scope="col" colspan="${(until-from)/layout.step}">${clockLabel(from)}–${clockLabel(until)}</th>`)}return `<section class="card aligned-schedule"><div class="section-head"><h2>Weekly timetable</h2><span class="small muted">Cairo time</span></div><div class="table-wrap"><table class="schedule-table"><colgroup><col class="schedule-day-column"><col span="${layout.slots}"></colgroup><thead><tr><th scope="col">Day</th>${headers.join('')}</tr></thead><tbody>${days.map(day=>{const lanes=layout.days.get(day)||[[]];return lanes.map((lane,index)=>`<tr class="${day===U.TODAY?'schedule-today':''}">${index===0?`<th scope="row" class="schedule-day" rowspan="${lanes.length}"><strong>${U.date(day,{weekday:'short'})}</strong><span>${U.date(day)}</span>${day===U.TODAY?'<small>Today</small>':''}</th>`:''}${lane.length?rowCells(lane,layout).map(cell=>{if(!cell.event)return `<td colspan="${cell.span}" class="schedule-free"></td>`;const s=cell.event,title=kind(s);return `<td colspan="${cell.span}" class="schedule-slot"><button class="timetable-class subject-colored ${title==='Section'?'is-section':''} ${s.status==='cancelled'?'is-cancelled':''}" style="${U.subjectStyle(s.course_id)}" data-form="class_sessions" data-id="${s.id}" aria-label="${esc(U.course(s.course_id)?.name)} · ${esc(title)} · ${shortTime(s.starts_at)}–${shortTime(s.ends_at)}"><div class="timetable-time">${shortTime(s.starts_at)}–${shortTime(s.ends_at)}</div><strong>${esc(U.course(s.course_id)?.course_code)}</strong><span class="timetable-name">${esc(U.course(s.course_id)?.name)}</span><div class="timetable-class-footer"><span>${esc(U.roomLabel(s.room_id))}</span><b>${s.status==='cancelled'?'Cancelled':esc(title)}</b></div></button></td>`}).join(''):`<td class="schedule-free empty-day" colspan="${layout.slots}">No classes</td>`}</tr>`).join('')}).join('')}</tbody></table></div><div class="timetable-legend"><span><i></i>Lecture</span><span><i class="section-key"></i>Section</span><span>Tap a class to edit</span></div></section>`}
const update=mount(()=>{let first=start(),days=Array.from({length:7},(_,i)=>{let d=new Date(first);d.setUTCDate(d.getUTCDate()+i);return d.toISOString().slice(0,10)}),sessions=db.class_sessions.filter(s=>days.includes(U.day(s.starts_at))&&(!courseFilter||s.course_id===courseFilter)),schedules=db.schedules.filter(s=>(!courseFilter||s.course_id===courseFilter)&&s.is_active),hours=schedules.reduce((total,s)=>{let a=s.starts_at_local.split(':').map(Number),b=s.ends_at_local.split(':').map(Number);return total+(b[0]*60+b[1]-a[0]*60-a[1])/60},0);return heading('YOUR WEEK','Schedule.','Your classes and rooms, at a glance.','<div class="import-toolbar-actions"><a class="btn" href="import.html">Import file</a>'+button('Add schedule','schedules')+'</div>')+`<div class="schedule-summary"><span>${icon('book')}<strong>${db.courses.length}</strong> courses</span><span>${icon('calendar')}<strong>${schedules.length}</strong> weekly classes</span><span>${icon('clock')}<strong>${hours}</strong> class hours</span><span class="schedule-source">Transcribed from your timetable</span></div><div class="toolbar"><div class="tabs"><button data-view="week" class="${view==='week'?'active':''}">Week</button><button data-view="list" class="${view==='list'?'active':''}">Agenda</button></div><div class="actions"><button class="btn" data-week="-1" aria-label="Previous week">←</button><button class="btn" data-week="0" aria-label="Return to current week">${U.date(days[0])} – ${U.date(days[6])}</button><button class="btn" data-week="1" aria-label="Next week">→</button></div></div><div class="toolbar"><details class="schedule-manage"><summary class="btn">Manage schedule</summary><div><button class="btn" data-view="recurring">Recurring classes</button><button class="btn" data-view="rooms">Rooms</button><a class="btn" href="courses.html">Courses</a></div></details><label class="small muted">Course <select id="course-filter" aria-label="Filter course"><option value="">All courses</option>${db.courses.map(c=>`<option value="${c.id}" ${c.id===courseFilter?'selected':''}>${esc(c.course_code)} · ${esc(c.name)}</option>`).join('')}</select></label>${button('One-off class','class_sessions')}</div>${view==='week'?weekBoard(days,sessions):view==='list'?section('This week’s classes',days.map(day=>`<div class="agenda-day"><div class="agenda-day-heading"><h3>${U.date(day,{weekday:'long',month:'short',day:'numeric'})}</h3>${day===U.TODAY?tag('Today','blue'):''}</div>${sessions.filter(s=>U.day(s.starts_at)===day).sort((a,b)=>new Date(a.starts_at)-new Date(b.starts_at)).map((s,i)=>U.sessionRow(s,i)).join('')||'<p class="small muted agenda-free">No classes scheduled. A little room to breathe.</p>'}</div>`).join('')):view==='rooms'?section('Rooms from your timetable',`<div class="grid3">${db.rooms.map(r=>`<div class="study-day"><div class="section-head"><h3>${esc(U.roomLabel(r.id))}</h3>${edit('rooms',r.id)}</div><p class="small muted">${esc([r.building,r.campus].filter(Boolean).join(' · ')||'Location details not provided')}</p></div>`).join('')}</div>`,button('Add room','rooms')):section('Weekly recurring schedules',`<div class="table-wrap"><table><thead><tr><th>Course</th><th>Class type</th><th>Day</th><th>Time</th><th>Room</th><th></th></tr></thead><tbody>${db.schedules.filter(s=>!courseFilter||s.course_id===courseFilter).slice().sort((a,b)=>((a.weekday+1)%7)-((b.weekday+1)%7)||a.starts_at_local.localeCompare(b.starts_at_local)).map(s=>`<tr><td>${esc(U.course(s.course_id)?.course_code)}</td><td>${tag(s.title,s.title==='Lecture'?'blue':'')}</td><td>${['','Monday','Tuesday','Wednesday','Thursday','Friday','Saturday','Sunday'][s.weekday]}</td><td>${s.starts_at_local}–${s.ends_at_local}</td><td>${esc(U.roomLabel(s.room_id))}</td><td>${edit('schedules',s.id)}</td></tr>`).join('')}</tbody></table></div>`)}`});
document.addEventListener('click',e=>{let v=e.target.closest('[data-view]'),w=e.target.closest('[data-week]');if(v){view=v.dataset.view;update()}if(w){offset=Number(w.dataset.week)===0?0:offset+Number(w.dataset.week);update()}});document.addEventListener('change',e=>{if(e.target.id==='course-filter'){courseFilter=e.target.value;update()}});
